static PointerRNA NodePanelState_rna_properties_get(CollectionPropertyIterator *iter)
{
    PropCollectionGetFunc fn = rna_builtin_properties_get;
    return fn(iter);
}

void NodePanelState_rna_properties_begin(CollectionPropertyIterator *iter, PointerRNA *ptr)
{

    *iter = {};
    iter->parent = *ptr;
    iter->prop = &rna_NodePanelState_rna_properties;

    PropCollectionBeginFunc fn = rna_builtin_properties_begin;
    fn(iter, ptr);

    if (iter->valid) {
        iter->ptr = NodePanelState_rna_properties_get(iter);
    }
}

void NodePanelState_rna_properties_next(CollectionPropertyIterator *iter)
{
    PropCollectionNextFunc fn = rna_builtin_properties_next;
    fn(iter);

    if (iter->valid) {
        iter->ptr = NodePanelState_rna_properties_get(iter);
    }
}

void NodePanelState_rna_properties_end(CollectionPropertyIterator *iter)
{
    PropCollectionEndFunc fn = rna_iterator_listbase_end;
    fn(iter);
}

bool NodePanelState_rna_properties_lookup_string(PointerRNA *ptr, const char *key, PointerRNA *r_ptr)
{
    PropCollectionLookupStringFunc fn = rna_builtin_properties_lookup_string;
    return fn(ptr, key, r_ptr);
}

PointerRNA NodePanelState_rna_type_get(PointerRNA *ptr)
{
    PropPointerGetFunc fn = rna_builtin_type_get;
    return fn(ptr);
}

int NodePanelState_identifier_get(PointerRNA *ptr)
{
    bNodePanelState *data = (bNodePanelState *)(ptr->data);
    return (int)(data->identifier);
}

bool NodePanelState_is_collapsed_get(PointerRNA *ptr)
{
    bNodePanelState *data = (bNodePanelState *)(ptr->data);
    return ((uint64_t(data->flag) & 1) != 0);
}

void NodePanelState_is_collapsed_set(PointerRNA *ptr, bool value)
{
    bNodePanelState *data = (bNodePanelState *)(ptr->data);
    if (value) { data->flag = std::remove_reference_t<decltype(data->flag)>(uint64_t(data->flag) | 1); }
    else { data->flag = std::remove_reference_t<decltype(data->flag)>(uint64_t(data->flag) & ~uint64_t(1)); }
}

