int NodeTree_description_length(PointerRNA *ptr)
{
    bNodeTree *data = (bNodeTree *)(ptr->data);
    return (data->description == nullptr) ? 0 : strlen(data->description);
}

void NodeTree_description_set(PointerRNA *ptr, const char *value)
{
    bNodeTree *data = (bNodeTree *)(ptr->data);
    if (data->description != nullptr) { MEM_delete(data->description); }
    const size_t length = strlen(value);
    if (length > 0) {
        data->description = MEM_new_array_uninitialized<char>(length + 1, __func__);
        memcpy(data->description, value, length + 1);
    } else { data->description = nullptr; }
}

