static PointerRNA NodeTree_nodes_get(CollectionPropertyIterator *iter)
{
    return RNA_pointer_create_with_parent(iter->parent, RNA_Node, rna_iterator_listbase_get(iter));
}

void NodeTree_nodes_begin(CollectionPropertyIterator *iter, PointerRNA *ptr)
{
    bNodeTree *data = (bNodeTree *)(ptr->data);

    *iter = {};
    iter->parent = *ptr;
    iter->prop = &rna_NodeTree_nodes;

    rna_iterator_listbase_begin(iter, ptr, &data->nodes, nullptr);

    if (iter->valid) {
        iter->ptr = NodeTree_nodes_get(iter);
    }
}

void NodeTree_nodes_next(CollectionPropertyIterator *iter)
{
    PropCollectionNextFunc fn = rna_iterator_listbase_next;
    fn(iter);

    if (iter->valid) {
        iter->ptr = NodeTree_nodes_get(iter);
    }
}

void NodeTree_nodes_end(CollectionPropertyIterator *iter)
{
    PropCollectionEndFunc fn = rna_iterator_listbase_end;
    fn(iter);
}

bool NodeTree_nodes_lookup_int(PointerRNA *ptr, int index, PointerRNA *r_ptr)
{
    bool found = false;
    CollectionPropertyIterator iter;

    NodeTree_nodes_begin(&iter, ptr);

    if (iter.valid) {
        ListBaseIterator *internal = &iter.internal.listbase;
        if (internal->skip) {
            while (index-- > 0 && iter.valid) {
                rna_iterator_listbase_next(&iter);
            }
            found = (index == -1 && iter.valid);
        }
        else {
            while (index-- > 0 && internal->link) {
                internal->link = internal->link->next;
            }
            found = (index == -1 && internal->link);
        }
        if (found) { *r_ptr = NodeTree_nodes_get(&iter); }
    }

    NodeTree_nodes_end(&iter);

    return found;
}

int Node_name_length(PointerRNA *);
void Node_name_get(PointerRNA *, char *);

bool NodeTree_nodes_lookup_string(PointerRNA *ptr, const char *key, PointerRNA *r_ptr)
{
    bool found = false;
    CollectionPropertyIterator iter;
    char namebuf[1024];
    char *name;

    NodeTree_nodes_begin(&iter, ptr);

    while (iter.valid) {
        if (iter.ptr.data) {
            int namelen = Node_name_length(&iter.ptr);
            if (namelen < 1024) {
                Node_name_get(&iter.ptr, namebuf);
                if (strcmp(namebuf, key) == 0) {
                    found = true;
                    *r_ptr = iter.ptr;
                    break;
                }
            }
            else {
                name = MEM_new_array_uninitialized<char>(size_t(namelen) + 1,
                                               "name string");
                Node_name_get(&iter.ptr, name);
                if (strcmp(name, key) == 0) {
                    MEM_delete(name);

                    found = true;
                    *r_ptr = iter.ptr;
                    break;
                }
                else {
                    MEM_delete(name);
                }
            }
        }
        NodeTree_nodes_next(&iter);
    }
    NodeTree_nodes_end(&iter);

    return found;
}

