{
    bNode *data = (bNode *)(ptr->data);
    return RNA_pointer_create_with_parent(*ptr, RNA_Text, data->id);
}

void ShaderNodeScript_script_set(PointerRNA *ptr, PointerRNA value, ReportList *reports)
{
    bNode *data = (bNode *)(ptr->data);
    if (value.data && ptr->owner_id && value.owner_id && !BKE_id_can_use_id(*ptr->owner_id, *value.owner_id)) {
      return;
    }

    if (data->id) {
        id_us_min((ID *)data->id);
    }
    if (value.data) {
        id_us_plus((ID *)value.data);
    }
    *(void **)&data->id = value.data;
}

