static PointerRNA CompositorNodeCryptomatteV2_entries_get(CollectionPropertyIterator *iter)
{
    return RNA_pointer_create_with_parent(iter->parent, RNA_CryptomatteEntry, rna_iterator_listbase_get(iter));
}

void CompositorNodeCryptomatteV2_entries_begin(CollectionPropertyIterator *iter, PointerRNA *ptr)
{
    NodeCryptomatte *data = (NodeCryptomatte *)(((bNode *)ptr->data)->storage);

    *iter = {};
    iter->parent = *ptr;
    iter->prop = &rna_CompositorNodeCryptomatteV2_entries;

    rna_iterator_listbase_begin(iter, ptr, &data->entries, nullptr);

    if (iter->valid) {
        iter->ptr = CompositorNodeCryptomatteV2_entries_get(iter);
    }
}

void CompositorNodeCryptomatteV2_entries_next(CollectionPropertyIterator *iter)
{
    PropCollectionNextFunc fn = rna_iterator_listbase_next;
    fn(iter);

    if (iter->valid) {
        iter->ptr = CompositorNodeCryptomatteV2_entries_get(iter);
    }
}

void CompositorNodeCryptomatteV2_entries_end(CollectionPropertyIterator *iter)
{
    PropCollectionEndFunc fn = rna_iterator_listbase_end;
    fn(iter);
}

bool CompositorNodeCryptomatteV2_entries_lookup_int(PointerRNA *ptr, int index, PointerRNA *r_ptr)
{
    bool found = false;
    CollectionPropertyIterator iter;

    CompositorNodeCryptomatteV2_entries_begin(&iter, ptr);

    if (iter.valid) {
        ListBaseIterator *internal = &iter.internal.listbase;
        if (internal->skip) {
            while (index-- > 0 && iter.valid) {
                rna_iterator_listbase_next(&iter);
            }
            found = (index == -1 && iter.valid);
        }
        else {
            while (index-- > 0 && internal->link) {
                internal->link = internal->link->next;
            }
            found = (index == -1 && internal->link);
        }
        if (found) { *r_ptr = CompositorNodeCryptomatteV2_entries_get(&iter); }
    }

    CompositorNodeCryptomatteV2_entries_end(&iter);

    return found;
}

int CryptomatteEntry_name_length(PointerRNA *);
void CryptomatteEntry_name_get(PointerRNA *, char *);

bool CompositorNodeCryptomatteV2_entries_lookup_string(PointerRNA *ptr, const char *key, PointerRNA *r_ptr)
{
    bool found = false;
    CollectionPropertyIterator iter;
    char namebuf[1024];
    char *name;

    CompositorNodeCryptomatteV2_entries_begin(&iter, ptr);

    while (iter.valid) {
        if (iter.ptr.data) {
            int namelen = CryptomatteEntry_name_length(&iter.ptr);
            if (namelen < 1024) {
                CryptomatteEntry_name_get(&iter.ptr, namebuf);
                if (strcmp(namebuf, key) == 0) {
                    found = true;
                    *r_ptr = iter.ptr;
                    break;
                }
            }
            else {
                name = MEM_new_array_uninitialized<char>(size_t(namelen) + 1,
                                               "name string");
                CryptomatteEntry_name_get(&iter.ptr, name);
                if (strcmp(name, key) == 0) {
                    MEM_delete(name);

                    found = true;
                    *r_ptr = iter.ptr;
                    break;
                }
                else {
                    MEM_delete(name);
                }
            }
        }
        CompositorNodeCryptomatteV2_entries_next(&iter);
    }
    CompositorNodeCryptomatteV2_entries_end(&iter);

    return found;
}

