void CompositorNodeOutputFile_file_output_items_begin(CollectionPropertyIterator *iter, PointerRNA *ptr)
{
    NodeCompositorFileOutput *data = (NodeCompositorFileOutput *)(((bNode *)ptr->data)->storage);

    *iter = {};
    iter->parent = *ptr;
    iter->prop = &rna_CompositorNodeOutputFile_file_output_items;

    rna_iterator_array_begin(iter, ptr, data->items, sizeof(data->items[0]), data->items_count, 0, nullptr);

    if (iter->valid) {
        iter->ptr = CompositorNodeOutputFile_file_output_items_get(iter);
    }
}

void CompositorNodeOutputFile_file_output_items_next(CollectionPropertyIterator *iter)
{
    PropCollectionNextFunc fn = rna_iterator_array_next;
    fn(iter);

    if (iter->valid) {
        iter->ptr = CompositorNodeOutputFile_file_output_items_get(iter);
    }
}

void CompositorNodeOutputFile_file_output_items_end(CollectionPropertyIterator *iter)
{
    PropCollectionEndFunc fn = rna_iterator_array_end;
    fn(iter);
}

bool CompositorNodeOutputFile_file_output_items_lookup_int(PointerRNA *ptr, int index, PointerRNA *r_ptr)
{
    bool found = false;
    CollectionPropertyIterator iter;

    CompositorNodeOutputFile_file_output_items_begin(&iter, ptr);

    if (iter.valid) {
        ArrayIterator *internal = &iter.internal.array;
        if (index < 0 || index >= internal->length) {
#ifdef __GNUC__
            printf("Array iterator out of range: %s (index %d)\n", __func__, index);
#else
            printf("Array iterator out of range: (index %d)\n", index);
#endif
        }
        else if (internal->skip) {
            while (index-- > 0 && iter.valid) {
                rna_iterator_array_next(&iter);
            }
            found = (index == -1 && iter.valid);
        }
        else {
            internal->ptr += internal->itemsize * index;
            found = 1;
        }
        if (found) { *r_ptr = CompositorNodeOutputFile_file_output_items_get(&iter); }
    }

    CompositorNodeOutputFile_file_output_items_end(&iter);

    return found;
}

int NodeCompositorFileOutputItem_name_length(PointerRNA *);
void NodeCompositorFileOutputItem_name_get(PointerRNA *, char *);

bool CompositorNodeOutputFile_file_output_items_lookup_string(PointerRNA *ptr, const char *key, PointerRNA *r_ptr)
{
    bool found = false;
    CollectionPropertyIterator iter;
    char namebuf[1024];
    char *name;

    CompositorNodeOutputFile_file_output_items_begin(&iter, ptr);

    while (iter.valid) {
        if (iter.ptr.data) {
            int namelen = NodeCompositorFileOutputItem_name_length(&iter.ptr);
            if (namelen < 1024) {
                NodeCompositorFileOutputItem_name_get(&iter.ptr, namebuf);
                if (strcmp(namebuf, key) == 0) {
                    found = true;
                    *r_ptr = iter.ptr;
                    break;
                }
            }
            else {
                name = MEM_new_array_uninitialized<char>(size_t(namelen) + 1,
                                               "name string");
                NodeCompositorFileOutputItem_name_get(&iter.ptr, name);
                if (strcmp(name, key) == 0) {
                    MEM_delete(name);

                    found = true;
                    *r_ptr = iter.ptr;
                    break;
                }
                else {
                    MEM_delete(name);
                }
            }
        }
        CompositorNodeOutputFile_file_output_items_next(&iter);
    }
    CompositorNodeOutputFile_file_output_items_end(&iter);

    return found;
}

